package com.yeyamo_mobile.api.recommendation_service.infrastructure.messaging;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class LegacyUserEventConsumer{private final RecommendationEventConsumer delegate;public LegacyUserEventConsumer(RecommendationEventConsumer d){delegate=d;}@KafkaListener(topics="${yeyamo.kafka.topics.legacy-user-events:user-events}",groupId="${spring.kafka.consumer.group-id:recommendation-service}")@Transactional public void consume(String raw)throws Exception{delegate.user(raw);}}
